package yks

import yks.utils.*
import yks.types.*
import kotlin.test.*

/**
 * Wire compatibility tests against binary fixtures generated by JavaScript yjs.
 * Each test decodes a V1 update produced by yjs and verifies the resulting state.
 *
 * Fixtures generated by fixtures/generate.mjs using yjs npm package.
 * Hex constants come from WireCompatFixtures (generated object).
 */
class WireCompatTest {

    private fun hexToBytes(hex: String): ByteArray {
        val result = ByteArray(hex.length / 2)
        for (i in result.indices) {
            result[i] = hex.substring(i * 2, i * 2 + 2).toInt(16).toByte()
        }
        return result
    }

    private fun toHex(bytes: ByteArray): String {
        return bytes.joinToString("") {
            val v = it.toInt() and 0xFF
            val hi = v shr 4
            val lo = v and 0x0F
            "${HEX_CHARS[hi]}${HEX_CHARS[lo]}"
        }
    }

    companion object {
        private const val HEX_CHARS = "0123456789abcdef"
    }

    private fun applyFixture(updateHex: String): Doc {
        val doc = Doc()
        val update = hexToBytes(updateHex)
        applyUpdate(doc, update)
        return doc
    }

