    @Test
    fun testEncodeArrayFloats() {
        // yjs uses writeFloat32 for 1.5f (tag 124) and writeFloat64 for others (tag 123).
        // Our writeAny uses unified Number dispatch: integer-valued -> tag 125, fractional -> tag 123 (float64).
        // So byte-exact match may fail for floats that yjs encodes as float32.
        // We verify decode + state instead.
        val doc = Doc()
        doc.clientID = WireCompatFixtures.SINGLE_DOC_V1_ARRAY_FLOATS_CLIENT_ID
        val arr = doc.getArray("arr")
        arr.push(listOf(1.5, -2.7, 0, 3.14159, -0.001))
        // Verify round-trip state: encode, decode into fresh doc, check values
        val update = encodeStateAsUpdate(doc)
        val doc2 = Doc()
        applyUpdate(doc2, update)
        val arr2 = doc2.getArray("arr")
        assertEquals(5, arr2.length)
        assertEquals(1.5, (arr2.get(0) as Number).toDouble(), 0.0001)
        assertEquals(-2.7, (arr2.get(1) as Number).toDouble(), 0.0001)
        // 0 is integer-encoded by us but float-encoded as float32 by yjs; decoded value is equivalent
        assertEquals(0.0, (arr2.get(2) as Number).toDouble(), 0.0)
        assertEquals(3.14159, (arr2.get(3) as Number).toDouble(), 0.00001)
        assertEquals(-0.001, (arr2.get(4) as Number).toDouble(), 0.00001)
    }

    @Test
    fun testEncodeArrayLargeInts() {
        // yjs encodes -2147483648 as float32 (tag 124: 0x7ccf000000).
        // Our writeAny encodes it differently. We verify state equivalence instead.
        val doc = Doc()
        doc.clientID = WireCompatFixtures.SINGLE_DOC_V1_ARRAY_LARGE_INTS_CLIENT_ID
        val arr = doc.getArray("arr")
        arr.push(listOf(0, -1, 2147483647, -2147483648, 1000000))
        val update = encodeStateAsUpdate(doc)
        val doc2 = Doc()
        applyUpdate(doc2, update)
        val arr2 = doc2.getArray("arr")
        assertEquals(5, arr2.length)
        assertEquals(0, arr2.get(0))
        assertEquals(-1, arr2.get(1))
        assertEquals(2147483647, arr2.get(2))
        assertEquals(-2147483648.0, (arr2.get(3) as Number).toDouble(), 0.0)
        assertEquals(1000000, arr2.get(4))
    }

