        val doc = Doc()
        doc.clientID = WireCompatFixtures.DELETE_OPS_V1_TEXT_EDITING_CLIENT_ID
        val text = doc.getText("text")
        text.insert(0, "Hello")
        text.insert(5, " World")
        text.delete(5, 1)
        text.insert(5, ", ")
        assertEquals("Hello, World", text.toString())
        // Round-trip: encode, decode, verify state
        val update = encodeStateAsUpdate(doc)
        val doc2 = Doc()
        applyUpdate(doc2, update)
        assertEquals("Hello, World", doc2.getText("text").toString())
    }

