    @Test
    fun testStateVectorRoundTrip() {
        val svHex = WireCompatFixtures.SINGLE_DOC_V1_ARRAY_INTS_STATE_VECTOR
        val sv = decodeStateVector(hexToBytes(svHex))
        val reencoded = encodeStateVectorFromMap(sv)
        assertEquals(svHex, toHex(reencoded))
    }

    @Test
    fun testCrossApplyKotlinToYjsFormat() {
        // Create doc in Kotlin, encode, apply to a fresh doc, verify state
        val doc1 = Doc()
        doc1.clientID = 42
        val arr1 = doc1.getArray("data")
        arr1.push(listOf("hello", 123, true))

        val update = encodeStateAsUpdate(doc1)

        val doc2 = Doc()
        applyUpdate(doc2, update)
        val arr2 = doc2.getArray("data")
        assertEquals(listOf("hello", 123, true), arr2.toArray())
    }

    @Test
    fun testTwoClientSync() {
        // Apply the merged state from two yjs docs
        val doc = applyFixture(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_MERGED_UPDATE)
        val arr = doc.getArray("arr")
        assertEquals(4, arr.length)
        val items = arr.toArray().toSet()
        assertTrue(items.contains("a"))
        assertTrue(items.contains("b"))
        assertTrue(items.contains("c"))
        assertTrue(items.contains("d"))
    }

    @Test
    fun testIncrementalUpdate() {
        // Apply full update
        val doc = Doc()
        val doc1 = Doc()
        doc1.clientID = 11
        val arr1 = doc1.getArray("arr")
        arr1.push(listOf("first"))
        val fullForFirst = encodeStateAsUpdate(doc1)
        applyUpdate(doc, fullForFirst)

        // Apply incremental from yjs
        val incrementalHex = "01010b01880b000177067365636f6e6400"
        applyUpdate(doc, hexToBytes(incrementalHex))

        val arr = doc.getArray("arr")
        assertEquals(listOf("first", "second"), arr.toArray())
    }
